mapper.select:
SELECT 
FROM book b
LEFT JOIN lending_stock s ON s.book_id = b.book_id
WHERE b.status = 'PUBLISHED'
  AND b.book_id > #{afterId}

  AND b.title LIKE CONCAT(#{query}, '%')


  AND b.category_id = #{categoryId}


  AND b.language = #{language}


  AND b.format = #{format}

ORDER BY b.book_id
LIMIT #{limit}

mapper.insert:
INSERT INTO book(
  book_id, isbn, title, subtitle, authors, publisher, category_id, language,
  description, cover_url, published_date, format, status, version, created_at, updated_at
) VALUES (
  #{bookId}, #{isbn}, #{title}, #{subtitle}, CAST(#{authorsJson} AS JSON), #{publisher},
  #{categoryId}, #{language}, #{description}, #{coverUrl}, #{publishedDate}, #{format},
  'DRAFT', 1, #{now}, #{now}
)

mapper.update:
UPDATE book
SET status = #{status}, version = version + 1, updated_at = #{now}
WHERE book_id = #{bookId} AND status != #{status}

UPDATE lending_stock
SET available_copies = available_copies + (#{newTotal} - total_copies),
    total_copies = #{newTotal}, version = version + 1, updated_at = #{now}
WHERE book_id = #{bookId}
  AND #{newTotal} BETWEEN 0 AND 100000
  AND available_copies + (#{newTotal} - total_copies) >= 0

UPDATE projection_control
SET generation = generation + 1, state = 'DIRTY', owner_token = NULL,
    lease_until = NULL, updated_at = #{now}
WHERE resource_type = 'BOOK' AND resource_id = #{bookId}

mapper.select:
SELECT generation
FROM projection_control
WHERE resource_type = 'BOOK' AND resource_id = #{bookId}
